def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    opp_coops = n - opp_defects
    last_m, last_o = history[-1]

    if last_o == 'C':
        if last_m == 'C':
            return 'C'
        else:
            if opp_coops >= n * 0.8 and my_defects < n * 0.5:
                return 'D'
            return 'C'
    else:
        if last_m == 'C':
            recent_opp_d = sum(1 for i in range(max(0, n-5), n) if history[i][1] == 'D')
            if recent_opp_d <= 1:
                return 'C'
            return 'D'
        else:
            if opp_coops > 0:
                dd_streak = 0
                for i in range(n-1, -1, -1):
                    if history[i][0] == 'D' and history[i][1] == 'D':
                        dd_streak += 1
                    else:
                        break
                if dd_streak >= 2:
                    recent_my_c = any(history[i][0] == 'C' for i in range(max(0, n-2), n))
                    if not recent_my_c:
                        return 'C'
                return 'D'
            else:
                peace_failed = False
                for i in range(2, n):
                    if (history[i][0] == 'C' and history[i][1] == 'D' and
                        history[i-1][0] == 'C' and history[i-1][1] == 'D' and
                        history[i-2][0] == 'D' and history[i-2][1] == 'D'):
                        peace_failed = True
                        break
                if peace_failed:
                    return 'D'
                if n >= 10 and history[-1][0] == 'C' and history[-1][1] == 'D':
                    if n == 1 or not (history[-2][0] == 'C' and history[-2][1] == 'D'):
                        return 'C'
                if n >= 10:
                    if all(history[i][0] == 'D' for i in range(n-5, n)):
                        return 'C'
                return 'D'
